import { describe, expect, it } from 'vitest';
import { VoiceResponse } from '../src/cloud/texml.js';

// Expected documents were generated by twilio's TwiML builder before it was removed, so TeXML output is unchanged.
const cases: [string, (r: VoiceResponse) => void, string][] = [
  ["empty", () => {},
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Response/>"],
  ["hangup", r => r.hangup(),
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Response><Hangup/></Response>"],
  ["escaped say", r => { r.say('Tom & Jerry <test> "quoted" it\'s'); r.hangup(); },
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Response><Say>Tom &amp; Jerry &lt;test&gt; \"quoted\" it's</Say><Hangup/></Response>"],
  ["probe gather", r => { r.gather({ input: ['dtmf'], numDigits: 8, timeout: 10, action: 'https://x.test/a?b=1&c=2', method: 'POST' }); r.hangup(); },
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Response><Gather input=\"dtmf\" numDigits=\"8\" timeout=\"10\" action=\"https://x.test/a?b=1&amp;c=2\" method=\"POST\"/><Hangup/></Response>"],
  ["gather with say", r => { r.gather({ input: ['dtmf'], numDigits: 1, timeout: 15, method: 'POST', action: 'https://x.test/p' }).say('Hello, press 1.'); r.hangup(); },
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Response><Gather input=\"dtmf\" numDigits=\"1\" timeout=\"15\" method=\"POST\" action=\"https://x.test/p\"><Say>Hello, press 1.</Say></Gather><Hangup/></Response>"],
  ["play digits", r => { r.pause({ length: 2 }); r.play({ digits: '12345678' }); r.pause({ length: 2 }); r.hangup(); },
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Response><Pause length=\"2\"/><Play digits=\"12345678\"/><Pause length=\"2\"/><Hangup/></Response>"],
  ["voicemail", r => { r.stop().stream({ name: 'shield-live' }); r.say('Sorry'); r.record({ maxLength: 60, timeout: 0, finishOnKey: '#', playBeep: true, channels: 'single', format: 'mp3', method: 'POST', action: 'https://x.test/rec', recordingStatusCallback: 'https://x.test/rs', recordingStatusCallbackMethod: 'POST' }); r.hangup(); },
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Response><Stop><Stream name=\"shield-live\"/></Stop><Say>Sorry</Say><Record maxLength=\"60\" timeout=\"0\" finishOnKey=\"#\" playBeep=\"true\" channels=\"single\" format=\"mp3\" method=\"POST\" action=\"https://x.test/rec\" recordingStatusCallback=\"https://x.test/rs\" recordingStatusCallbackMethod=\"POST\"/><Hangup/></Response>"],
  ["offer with monitoring", r => {
    r.stop().stream({ name: 'shield-live' }); r.say('Please hold.');
    r.start().transcription({ transcriptionEngine: 'Parakeet', transcriptionTracks: 'both', transcriptionCallback: 'https://x.test/m', transcriptionCallbackMethod: 'POST' });
    const d = r.dial({ callerId: '+12025550109', answerOnBridge: true, timeout: 20, timeLimit: 300, action: 'https://x.test/de', method: 'POST' });
    d.number({ url: 'https://x.test/w', method: 'POST', statusCallback: 'https://x.test/c', statusCallbackMethod: 'POST', statusCallbackEvent: ['initiated', 'ringing', 'answered'] }, '+12025550101');
    r.hangup();
  },
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Response><Stop><Stream name=\"shield-live\"/></Stop><Say>Please hold.</Say><Start><Transcription transcriptionEngine=\"Parakeet\" transcriptionTracks=\"both\" transcriptionCallback=\"https://x.test/m\" transcriptionCallbackMethod=\"POST\"/></Start><Dial callerId=\"+12025550109\" answerOnBridge=\"true\" timeout=\"20\" timeLimit=\"300\" action=\"https://x.test/de\" method=\"POST\"><Number url=\"https://x.test/w\" method=\"POST\" statusCallback=\"https://x.test/c\" statusCallbackMethod=\"POST\" statusCallbackEvent=\"initiated ringing answered\">+12025550101</Number></Dial><Hangup/></Response>"],
];

describe('TeXML builder', () => {
  it.each(cases)('renders %s exactly', (_name, fill, expected) => {
    const r = new VoiceResponse(); fill(r); expect(r.toString()).toBe(expected);
  });
});
